/// Ended and, by its restart policy, not restarted.
pub const SUPERVISOR_UNIT_STATE_STOPPED: i32 = 7;
/// Given up on: the restart limit tripped, or a critical unit died.
pub const SUPERVISOR_UNIT_STATE_FAILED: i32 = 8;
/// Held stopped because its parent= unit stopped, failed or is itself degraded.
pub const SUPERVISOR_UNIT_STATE_DEGRADED: i32 = 9;

// supervisor_restart
/// The restart= policy of a supervised unit.
/// Never restarted.
pub const SUPERVISOR_RESTART_NEVER: i32 = 0;
/// Restarted unless it exited cleanly with status 0.
pub const SUPERVISOR_RESTART_ON_FAILURE: i32 = 1;
/// Restarted whenever it ends.
pub const SUPERVISOR_RESTART_ALWAYS: i32 = 2;

// supervisor_class
/// The class= of a supervised unit, what its death costs the system.
/// Given up on alone.
pub const SUPERVISOR_CLASS_OPTIONAL: i32 = 0;
/// Given up on; the system runs degraded.
pub const SUPERVISOR_CLASS_REQUIRED: i32 = 1;
/// Never restarted: its first death takes the system down.
pub const SUPERVISOR_CLASS_CRITICAL: i32 = 2;

// capability
/// Capability kinds, as ipc_endpoint_has_cap asks about them. Each is the kind
/// a manifest [[capabilities]] name grants (docs/architecture/10-capability-and-policy.md);
/// the kernel's capability_kind_t takes the same values.
/// io.port: x86 I/O port access.
pub const WASMOS_CAP_IO_PORT: i32 = 0;
/// irq.route: route hardware IRQ lines to an endpoint.
pub const WASMOS_CAP_IRQ_ROUTE: i32 = 1;
/// mmio.map: map MMIO regions.
pub const WASMOS_CAP_MMIO_MAP: i32 = 2;
/// dma.buffer: DMA buffer host calls.
pub const WASMOS_CAP_DMA_BUFFER: i32 = 3;
/// system.control: halt, reboot, power off.
pub const WASMOS_CAP_SYSTEM_CONTROL: i32 = 4;
/// subsystem.register: broker subsystems and exec-format handlers.
pub const WASMOS_CAP_SUBSYSTEM_REGISTER: i32 = 5;
/// svc.class: register under a virtual service class.
pub const WASMOS_CAP_SVC_CLASS_REGISTER: i32 = 6;
/// console.owner: register the console ring.
pub const WASMOS_CAP_CONSOLE_OWNER: i32 = 7;
/// spawn.grant: put hardware grants on a spawned child, directly or through the supervisor.
pub const WASMOS_CAP_SPAWN_GRANT: i32 = 8;
/// svc.control: submit, kill and declare the boot set at the supervisor.
pub const WASMOS_CAP_SVC_CONTROL: i32 = 9;
/// pci.config: read and write PCI configuration space (pci_config_read/pci_config_write).
pub const WASMOS_CAP_PCI_CONFIG: i32 = 10;
/// rtc.efi: read and set the clock through UEFI runtime services (rtc_efi_get/rtc_efi_set).
pub const WASMOS_CAP_RTC_EFI: i32 = 11;
/// inventory.device: publish PCI and ACPI device records (and the end of a bus scan) to device-manager's inventory.
pub const WASMOS_CAP_INVENTORY_DEVICE: i32 = 12;
/// inventory.storage: publish and retire block-device and volume records in device-manager's inventory.
pub const WASMOS_CAP_INVENTORY_STORAGE: i32 = 13;
/// keyring.register: register a trusted package-signing key with the kernel (the keyring service).
pub const WASMOS_CAP_KEYRING_REGISTER: i32 = 14;
/// keyring.admin: change what the keyring trusts -- add a publisher key, allow a package to start anyway (the trust utility, the console shell).
pub const WASMOS_CAP_KEYRING_ADMIN: i32 = 15;
